function pertama<T>(a: T[]): T | undefined {
  return a[0];
}
function terakhir<T>(a: T[]): T | undefined {
  return a[a.length - 1];
}
const menu = pertama(["kopi", "teh", "jus"]);
const harga = terakhir([18000, 12000, 15000]);
console.log(menu?.toUpperCase());
console.log(harga?.toFixed(2));

