cards.solution:
function acakSatu<T>(a: T[], posisi: number): T {
  if (posisi < 0 || posisi >= a.length) throw new Error("Posisi tidak valid");
  return a[posisi];
}
console.log(acakSatu(["kopi", "teh", "jus"], 2));
try {
  acakSatu([1, 2], 5);
} catch (e) {
  if (e instanceof Error) console.log(e.message);
}
